values ('aaaa0006-0000-4000-8000-000000000001', 'en', null, 'German A1 — First Steps', 'A CEFR A1 starter course that teaches German for absolute beginners: greet people, introduce yourself, count, order food, and ask simple questions with confidence.', 'A1', 'travel', 10, true, 'language', '{}')
